import{createHash}from"node:crypto";import{promises as fs}from"node:fs";import{createRequire}from"node:module";import path from"node:path";import{promisify}from"node:util";const require=createRequire(import.meta.url),fsExt=require("fs-ext"),flockAsync=promisify(fsExt.flock),LOCK_DIR_NAME="locks";export class SubscribeLockBusyError extends Error{lockPath;constructor(r){super(`subscribe lock busy path=${r}`),this.name="SubscribeLockBusyError",this.lockPath=r}}const isLockBusyError=r=>{if(!(r instanceof Error))return!1;const e=r.code;return"EWOULDBLOCK"===e||"EAGAIN"===e||"EACCES"===e};export const buildSubscribeLockKey=r=>{const e=JSON.stringify({url:r.bridge.url,userId:r.bridge.userId,token:r.bridge.token??"",protocol:r.bridge.protocol});return createHash("sha256").update(e).digest("hex").slice(0,24)};export const resolveSubscribeLockPath=r=>{const e=buildSubscribeLockKey(r),t=path.join(path.dirname(path.resolve(r.log.wsObsFile)),"locks");return{key:e,path:path.join(t,`subscribe-${e}.lock`)}};export async function acquireSubscribeLock(r){const e=resolveSubscribeLockPath(r.cfg);await fs.mkdir(path.dirname(e.path),{recursive:!0});const t=await fs.open(e.path,"a+",384);try{await flockAsync(t.fd,"exnb")}catch(r){if(await t.close().catch(()=>{}),isLockBusyError(r))throw new SubscribeLockBusyError(e.path);throw r}await t.truncate(0),await t.writeFile(`${JSON.stringify({pid:process.pid,acquiredAt:(new Date).toISOString(),key:e.key,bridgeUrl:r.cfg.bridge.url,instanceId:r.cfg.bridge.instanceId,deviceId:r.cfg.bridge.deviceId},null,2)}\n`,"utf8");let o=!1;return{key:e.key,path:e.path,release:async()=>{if(!o){o=!0;try{await flockAsync(t.fd,"un")}catch(t){r.logger.warn(`[lock] subscribe unlock failed path=${e.path} error=${t instanceof Error?t.message:String(t)}`)}finally{await t.close().catch(()=>{})}}}}}